window.CMAIExamples={en:["Pipe inner diameter 20 mm, flow 12 L/min. What is the mean velocity?","Tomatoes 2 kg at 6 CNY/kg; eggs 3 boxes at 12 CNY/box; shipping 5 CNY. Total?","A 1500 W device runs 2 hours/day for 30 days. Energy in kWh?","Calculate(2+3)*4."],"zh-CN":["\u7BA1\u5185\u5F8420\u6BEB\u7C73\uFF0C\u6BCF\u5206\u949F\u6D41\u8FC712\u5347\u6C34\uFF0C\u5E73\u5747\u6D41\u901F\u662F\u591A\u5C11\uFF1F","\u4E70\u897F\u7EA2\u67FF2\u516C\u65A4\uFF0C\u5355\u4EF76 CNY/kg\uFF1B\u9E21\u86CB3\u76D2\uFF0C\u5355\u4EF712 CNY/\u76D2\uFF1B\u8FD0\u8D395 CNY\u3002\u603B\u5171\u591A\u5C11\uFF1F","\u4E00\u53F0\u529F\u73871500 W\u7684\u8BBE\u5907\uFF0C\u6BCF\u5929\u8FD0\u884C2\u5C0F\u65F6\uFF0C\u6301\u7EED30\u5929\uFF0C\u7528\u7535\u591A\u5C11kWh\uFF1F","\u7528\u7B97\u5F0F(2+3)*4\u8BA1\u7B97\u7ED3\u679C\u3002"],hi:["\u092A\u093E\u0907\u092A \u0915\u093E \u092D\u0940\u0924\u0930\u0940 \u0935\u094D\u092F\u093E\u093820 mm \u0914\u0930 \u092A\u094D\u0930\u0935\u093E\u093912 L/min \u0939\u0948\u0964 \u0914\u0938\u0924 \u0917\u0924\u093F \u0915\u094D\u092F\u093E \u0939\u0948?","\u091F\u092E\u093E\u091F\u09302 kg, \u0915\u0940\u092E\u09246 CNY/kg; \u0905\u0902\u0921\u09473 \u0921\u093F\u092C\u094D\u092C\u0947, \u0915\u0940\u092E\u092412 CNY/\u0921\u093F\u092C\u094D\u092C\u093E; \u0921\u093F\u0932\u0940\u0935\u0930\u09405 CNY\u0964 \u0915\u0941\u0932?","1500 W \u0909\u092A\u0915\u0930\u0923 \u0930\u094B\u091C2 \u0918\u0902\u091F\u0947,30 \u0926\u093F\u0928 \u091A\u0932\u0924\u093E \u0939\u0948\u0964 \u0915\u093F\u0924\u0928\u0947 kWh?","(2+3)*4 \u0915\u0940 \u0917\u0923\u0928\u093E \u0915\u0930\u0947\u0902\u0964"],es:["Di\xE1metro interior 20 mm y caudal 12 L/min. \xBFVelocidad media?","Tomates 2 kg a 6 CNY/kg; huevos 3 cajas a 12 CNY/caja; env\xEDo 5 CNY. \xBFTotal?","Un aparato de 1500 W funciona 2 horas al d\xEDa durante 30 d\xEDas. \xBFEnerg\xEDa en kWh?","Calcula(2+3)*4."],ar:["\u0627\u0644\u0642\u0637\u0631 \u0627\u0644\u062F\u0627\u062E\u0644\u064A \u0644\u0644\u0623\u0646\u0628\u0648\u062820 mm \u0648\u0627\u0644\u062A\u062F\u0641\u064212 L/min. \u0645\u0627 \u0645\u062A\u0648\u0633\u0637 \u0627\u0644\u0633\u0631\u0639\u0629\u061F","\u0637\u0645\u0627\u0637\u06452 kg \u0628\u0633\u0639\u06316 CNY/kg\u061B \u0628\u064A\u06363 \u0639\u0644\u0628 \u0628\u0633\u0639\u063112 CNY/\u0639\u0644\u0628\u0629\u061B \u062A\u0648\u0635\u064A\u06445 CNY. \u0645\u0627 \u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A\u061F","\u062C\u0647\u0627\u0632 \u0628\u0642\u062F\u0631\u06291500 W \u064A\u0639\u0645\u0644 2 \u0633\u0627\u0639\u0627\u062A \u064A\u0648\u0645\u064A\u0627\u064B \u0644\u0645\u062F\u062930 \u064A\u0648\u0645\u0627\u064B. \u0643\u0645 \u064A\u0633\u062A\u0647\u0644\u0643 \u0628\u0648\u062D\u062F\u0629 kWh\u061F","\u0627\u062D\u0633\u0628(2+3)*4."],fr:["Diam\xE8tre int\xE9rieur 20 mm, d\xE9bit 12 L/min. Quelle vitesse moyenne ?","Tomates 2 kg \xE0 6 CNY/kg; \u0153ufs 3 bo\xEEtes \xE0 12 CNY/bo\xEEte; livraison 5 CNY. Total ?","Un appareil de 1500 W fonctionne 2 heures par jour pendant 30 jours. \xC9nergie en kWh ?","Calculez(2+3)*4."],bn:["\u09AA\u09BE\u0987\u09AA\u09C7\u09B0 \u09AD\u09C7\u09A4\u09B0\u09C7\u09B0 \u09AC\u09CD\u09AF\u09BE\u09B820 mm, \u09AA\u09CD\u09B0\u09AC\u09BE\u09B912 L/min\u0964 \u0997\u09A1\u09BC \u0997\u09A4\u09BF \u0995\u09A4?","\u099F\u09AE\u09C7\u099F\u09CB2 kg, \u09A6\u09BE\u09AE6 CNY/kg; \u09A1\u09BF\u09AE3 \u09AC\u09BE\u0995\u09CD\u09B8, \u09A6\u09BE\u09AE12 CNY/\u09AC\u09BE\u0995\u09CD\u09B8; \u09A1\u09C7\u09B2\u09BF\u09AD\u09BE\u09B0\u09BF5 CNY\u0964 \u09AE\u09CB\u099F \u0995\u09A4?","1500 W \u09AF\u09A8\u09CD\u09A4\u09CD\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u09A6\u09BF\u09A82 \u0998\u09A3\u09CD\u099F\u09BE,30 \u09A6\u09BF\u09A8 \u099A\u09B2\u09C7\u0964 \u0995\u09A4 kWh?","(2+3)*4 \u09B9\u09BF\u09B8\u09BE\u09AC \u0995\u09B0\u09C1\u09A8\u0964"],pt:["Di\xE2metro interno 20 mm, vaz\xE3o 12 L/min. Qual a velocidade m\xE9dia?","Tomates 2 kg a 6 CNY/kg; ovos 3 caixas a 12 CNY/caixa; frete 5 CNY. Total?","Um aparelho de 1500 W funciona 2 horas por dia por 30 dias. Energia em kWh?","Calcule(2+3)*4."],id:["Diameter dalam pipa 20 mm, debit 12 L/min. Berapa kecepatan rata-rata?","Tomat 2 kg seharga 6 CNY/kg; telur 3 kotak seharga 12 CNY/kotak; ongkir 5 CNY. Total?","Perangkat 1500 W berjalan 2 jam sehari selama 30 hari. Energi dalam kWh?","Hitung(2+3)*4."],ur:["\u067E\u0627\u0626\u067E \u06A9\u0627 \u0627\u0646\u062F\u0631\u0648\u0646\u06CC \u0642\u0637\u063120 mm \u0627\u0648\u0631 \u0628\u06C1\u0627\u062412 L/min \u06C1\u06D2\u06D4 \u0627\u0648\u0633\u0637 \u0631\u0641\u062A\u0627\u0631 \u06A9\u06CC\u0627 \u06C1\u06D2\u061F","\u0679\u0645\u0627\u0679\u06312 kg \u0642\u06CC\u0645\u062A6 CNY/kg\u061B \u0627\u0646\u0688\u06D23 \u0688\u0628\u06D2 \u0642\u06CC\u0645\u062A12 CNY/\u0688\u0628\u06C1\u061B \u062A\u0631\u0633\u06CC\u06445 CNY\u06D4 \u06A9\u0644\u061F","1500 W \u0622\u0644\u06C1 \u0631\u0648\u0632\u0627\u0646\u06C12 \u06AF\u06BE\u0646\u0679\u06D2\u060C30 \u062F\u0646 \u0686\u0644\u062A\u0627 \u06C1\u06D2\u06D4 \u06A9\u062A\u0646\u06D2 kWh\u061F","(2+3)*4 \u06A9\u0627 \u062D\u0633\u0627\u0628 \u06A9\u0631\u06CC\u06BA\u06D4"],ru:["\u0412\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u0438\u0439 \u0434\u0438\u0430\u043C\u0435\u0442\u044020 mm, \u0440\u0430\u0441\u0445\u043E\u043412 L/min. \u041A\u0430\u043A\u043E\u0432\u0430 \u0441\u0440\u0435\u0434\u043D\u044F\u044F \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C?","\u041F\u043E\u043C\u0438\u0434\u043E\u0440\u044B2 kg \u043F\u043E6 CNY/kg; \u044F\u0439\u0446\u04303 \u043A\u043E\u0440\u043E\u0431\u043A\u0438 \u043F\u043E12 CNY/\u043A\u043E\u0440\u043E\u0431\u043A\u0443; \u0434\u043E\u0441\u0442\u0430\u0432\u043A\u04305 CNY. \u0418\u0442\u043E\u0433\u043E?","\u041F\u0440\u0438\u0431\u043E\u04401500 W \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u04422 \u0447\u0430\u0441\u0430 \u0432 \u0434\u0435\u043D\u044C30 \u0434\u043D\u0435\u0439. \u042D\u043D\u0435\u0440\u0433\u0438\u044F \u0432 kWh?","\u0420\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u0439\u0442\u0435(2+3)*4."],de:["Rohrinnendurchmesser 20 mm, Durchfluss 12 L/min. Mittlere Geschwindigkeit?","Tomaten 2 kg zu 6 CNY/kg; Eier 3 Schachteln zu 12 CNY/Schachtel; Versand 5 CNY. Gesamt?","Ein 1500-W-Ger\xE4t l\xE4uft 2 Stunden t\xE4glich an 30 Tagen. Energie in kWh?","Berechne(2+3)*4."],ja:["\u7BA1\u306E\u5185\u5F8420 mm\u3001\u6D41\u91CF12 L/min\u3067\u3059\u3002\u5E73\u5747\u6D41\u901F\u306F\uFF1F","\u30C8\u30DE\u30C82 kg\u30016 CNY/kg\u3002\u53753\u7BB1\u300112 CNY/\u7BB1\u3002\u9001\u65995 CNY\u3002\u5408\u8A08\u306F\uFF1F","1500 W\u306E\u6A5F\u5668\u3092\u6BCE\u65E52\u6642\u9593\u300130\u65E5\u4F7F\u7528\u3002\u96FB\u529B\u91CF\u306F\u4F55kWh\uFF1F","(2+3)*4\u3092\u8A08\u7B97\u3057\u3066\u304F\u3060\u3055\u3044\u3002"],pcm:["Pipe inside diameter na 20 mm, flow na 12 L/min. Wetin be average speed?","Tomato 2 kg for 6 CNY/kg; egg 3 boxes for 12 CNY/box; delivery 5 CNY. Total?","1500 W device dey run 2 hours every day for 30 days. How many kWh?","Calculate(2+3)*4."],mr:["\u092A\u093E\u0907\u092A\u091A\u093E \u0906\u0924\u0940\u0932 \u0935\u094D\u092F\u093E\u093820 mm, \u092A\u094D\u0930\u0935\u093E\u093912 L/min \u0906\u0939\u0947. \u0938\u0930\u093E\u0938\u0930\u0940 \u0935\u0947\u0917 \u0915\u093F\u0924\u0940?","\u091F\u094B\u092E\u0945\u091F\u094B2 kg \u0926\u09306 CNY/kg; \u0905\u0902\u0921\u09403 \u092A\u0947\u091F\u094D\u092F\u093E \u0926\u093012 CNY/\u092A\u0947\u091F\u0940; \u0935\u093F\u0924\u0930\u09235 CNY. \u090F\u0915\u0942\u0923?","1500 W \u0909\u092A\u0915\u0930\u0923 \u0930\u094B\u091C2 \u0924\u093E\u0938,30 \u0926\u093F\u0935\u0938 \u091A\u093E\u0932\u0924\u0947. \u0915\u093F\u0924\u0940 kWh?","(2+3)*4 \u091A\u0940 \u0917\u0923\u0928\u093E \u0915\u0930\u093E."],vi:["\u0110\u01B0\u1EDDng k\xEDnh trong 20 mm, l\u01B0u l\u01B0\u1EE3ng 12 L/min. V\u1EADn t\u1ED1c trung b\xECnh?","C\xE0 chua 2 kg gi\xE1 6 CNY/kg; tr\u1EE9ng 3 h\u1ED9p gi\xE1 12 CNY/h\u1ED9p; ph\xED giao 5 CNY. T\u1ED5ng?","Thi\u1EBFt b\u1ECB1500 W ch\u1EA1y 2 gi\u1EDD m\u1ED7i ng\xE0y trong 30 ng\xE0y. \u0110i\u1EC7n n\u0103ng bao nhi\xEAu kWh?","T\xEDnh(2+3)*4."],te:["\u0C2A\u0C48\u0C2A\u0C41 \u0C32\u0C4B\u0C2A\u0C32\u0C3F \u0C35\u0C4D\u0C2F\u0C3E\u0C38\u0C0220 mm, \u0C2A\u0C4D\u0C30\u0C35\u0C3E\u0C39\u0C0212 L/min. \u0C38\u0C17\u0C1F\u0C41 \u0C35\u0C47\u0C17\u0C02 \u0C0E\u0C02\u0C24?","\u0C1F\u0C2E\u0C3E\u0C1F\u0C3E\u0C32\u0C412 kg \u0C27\u0C306 CNY/kg; \u0C17\u0C41\u0C21\u0C4D\u0C32\u0C413 \u0C2A\u0C46\u0C1F\u0C4D\u0C1F\u0C46\u0C32\u0C41 \u0C27\u0C3012 CNY/\u0C2A\u0C46\u0C1F\u0C4D\u0C1F\u0C46; \u0C21\u0C46\u0C32\u0C3F\u0C35\u0C30\u0C405 CNY. \u0C2E\u0C4A\u0C24\u0C4D\u0C24\u0C02?","1500 W \u0C2A\u0C30\u0C3F\u0C15\u0C30\u0C02 \u0C30\u0C4B\u0C1C\u0C422 \u0C17\u0C02\u0C1F\u0C32\u0C41,30 \u0C30\u0C4B\u0C1C\u0C41\u0C32\u0C41 \u0C2A\u0C28\u0C3F\u0C1A\u0C47\u0C38\u0C4D\u0C24\u0C41\u0C02\u0C26\u0C3F. \u0C0E\u0C28\u0C4D\u0C28\u0C3F kWh?","(2+3)*4 \u0C32\u0C46\u0C15\u0C4D\u0C15\u0C3F\u0C02\u0C1A\u0C02\u0C21\u0C3F."],sw:["Kipenyo cha ndani 20 mm, mtiririko 12 L/min. Kasi ya wastani ni nini?","Nyanya 2 kg kwa 6 CNY/kg; mayai 3 masanduku kwa 12 CNY/sanduku; usafirishaji 5 CNY. Jumla?","Kifaa cha 1500 W hutumika saa 2 kwa siku kwa siku 30. Nishati ya kWh?","Kokotoa(2+3)*4."],ha:["Diamitan cikin bututu 20 mm, kwarara 12 L/min. Menene matsakaicin gudu?","Tumatir 2 kg a 6 CNY/kg; \u0199wai 3 kwalaye a 12 CNY/kwali; kai kaya 5 CNY. Jimilla?","Na\u2019urar 1500 W tana aiki awa 2 kullum na kwanaki 30. Makamashi nawa a kWh?","Lissafa(2+3)*4."],tr:["Boru i\xE7 \xE7ap\u0131 20 mm, debi 12 L/min. Ortalama h\u0131z nedir?","Domates 2 kg,6 CNY/kg; yumurta 3 kutu,12 CNY/kutu; kargo 5 CNY. Toplam?","1500 W cihaz g\xFCnde 2 saat,30 g\xFCn \xE7al\u0131\u015F\u0131yor. Enerji ka\xE7 kWh?","(2+3)*4 hesapla."]};
